#!/bin/bash
# Requires the isolated sample app generated by run-ui-tests.sh to be installed.
# Measures real Vision work on synthetic images, with no artificial fetch delay.
set -euo pipefail
if [ "$#" -ne 2 ]; then
  echo 'Usage: benchmark-simulator.sh SIMULATOR_UDID OUTPUT_JSON' >&2
  exit 2
fi
shotr_container="$(xcrun simctl get_app_container "$1" com.calum.shots data)"
shotr_report="$shotr_container/Documents/scan-benchmark.json"
# This file is generated only by the sample app's explicit benchmark launch route.
if [ -f "$shotr_report" ]; then rm "$shotr_report"; fi
xcrun simctl launch --terminate-running-process "$1" com.calum.shots --benchmark-scan
python3 - "$shotr_report" "$2" <<'PY'
import json, pathlib, sys, time
source, output = map(pathlib.Path, sys.argv[1:])
deadline = time.monotonic() + 240
while time.monotonic() < deadline:
    try:
        result = json.loads(source.read_text())
    except (FileNotFoundError, json.JSONDecodeError):
        time.sleep(0.5)
        continue
    result['scope'] = 'iOS 27 simulator; 15 synthetic 600x1000 images; no PhotoKit or iCloud; AI availability recorded; no artificial delay'
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(result, indent=2) + '\n')
    print(output.read_text())
    break
else:
    raise SystemExit('No scan report after 240 seconds. Check the installed sample app and scan state.')
PY
